// Can be cancelled with preventDefault() to prevent selection. Used for implementing custom selection
// behaviour, preventing text selection during drag operations, or tracking when users begin selecting content.
func (e *clipPath) OnSelectStart(handler string) *clipPath {
	e.SetAttribute("onselectstart", handler)
	return e
}

// OnSelectionChange sets the onselectionchange attribute.
//
// Fired when the current text selection changes, including when the selection is extended, collapsed, or
// cleared. Used for implementing selection-dependent toolbars, tracking selected text for formatting tools,
// updating word counts, or providing contextual actions based on the current selection.
func (e *clipPath) OnSelectionChange(handler string) *clipPath {
	e.SetAttribute("onselectionchange", handler)
	return e
}

// SetAttribute sets a custom attribute on the element, escaping the value.
// For a pre-trusted value that must render verbatim, use SetAttributeRaw.
//
// The key is written to the rendered output verbatim. It is code, not
// data: pass a fixed, developer-controlled key. Never build the key from
// user input - a key containing a space, quote, "=", "/" or ">" changes
// the markup structure. The value is escaped; the key is not.
func (e *clipPath) SetAttribute(key string, value string) {
	value = node.EscapeAttribute(value)
	if e.attr == nil {
		e.attr = &[]node.Attribute{}
	}
	// Update existing attribute or add new one
	for i, attr := range *e.attr {
		if attr.Key == key {
			(*e.attr)[i].Value = value
			return
		}
	}
	*e.attr = append(*e.attr, node.Attribute{Key: key, Value: value})
}

// SetAttributeRaw sets a custom attribute without escaping its value. Use only
// with trusted values (mirrors RawText); prefer SetAttribute, which escapes.
// The key is written verbatim, as on SetAttribute; here the value is too.
func (e *clipPath) SetAttributeRaw(key string, value string) {
	if e.attr == nil {
		e.attr = &[]node.Attribute{}
	}
	for i, attr := range *e.attr {
		if attr.Key == key {
			(*e.attr)[i].Value = value
			return
		}
	}
	*e.attr = append(*e.attr, node.Attribute{Key: key, Value: value})
}

// Add appends children to the element.
func (e *clipPath) Add(children ...Shape) *clipPath {
	for _, child := range children {
		e.nodes = append(e.nodes, child)
	}
	return e
}

// Replace replaces all children with the provided ones.
func (e *clipPath) Replace(children ...Shape) *clipPath {
	e.nodes = make([]node.Node, len(children))
	for i, child := range children {
		e.nodes[i] = child
	}
	return e
}

// Dynamic marks this element for reactive tracking by the diff engine.
// The key is the element's stable identity across renders: the diff engine
// matches on it to detect changes and send targeted patches, so it must be
// unique within a render tree and must not change between renders. It
// renders, escaped, as the element's id attribute, so the key is also the
// DOM identity a patch consumer looks up and a morpher matches on. Setting
// ID to a different value on the same element panics at render.
func (e *clipPath) Dynamic(key string) *clipPath {
	e.dynamic = key
	return e
}

// IsDynamic reports whether this element has been marked for reactive tracking.
func (e *clipPath) IsDynamic() bool {
	return e.dynamic != ""
}

// DynamicKey returns the developer-assigned key for diff engine tracking.
// Returns an empty string if the element has not been marked as dynamic.
func (e *clipPath) DynamicKey() string {
	return e.dynamic
}

// Memoise sets the cache version for this element's subtree. The diff
// engine's memoisation layer (fluent-jit) skips rendering and diffing the
// subtree when the version matches the previous render. Opposite lifecycle
// to the Dynamic key: the key is stable identity, the version changes
// whenever the content does. Plain rendering ignores it entirely.
func (e *clipPath) Memoise(version any) *clipPath {
	e.memoise = version
	return e
}

// MemoiseKey returns the cache version set by Memoise, or nil when the
// element is not memoised. Satisfies the memoisation interface consumed
// by fluent-jit.
func (e *clipPath) MemoiseKey() any {
	return e.memoise
}

// Node interface implementation

// BufferHint seeds the buffer size used for pool allocation and returns
// the element, so it chains. A hint of zero or less is ignored. The next
// render's measured size replaces the hint - see RenderedSize.
func (e *clipPath) BufferHint(hint int) *clipPath {
	if hint > 0 {
		e.bufferhint.Store(int64(hint))
	}
	return e
}

// RenderedSize returns the most recent render's measured size in bytes,
// or the BufferHint value before the first render. Every render records
// its size, so a retained element self-tunes: the next render draws a
// right-sized buffer from the pool.
func (e *clipPath) RenderedSize() int {
	return int(e.bufferhint.Load())
}

// Render writes the element's HTML to w. Write errors are deliberately
// discarded - use WriteTo to observe them.
func (e *clipPath) Render(w io.Writer) {
	_, _ = e.WriteTo(w)
}

// WriteTo renders into a pooled buffer sized by the last measured render
// (or BufferHint before the first) and writes it to w, returning the byte
// count and any write error. Satisfies io.WriterTo. The size is measured
// before the buffer drains into w, so a retained element self-tunes.
func (e *clipPath) WriteTo(w io.Writer) (int64, error) {
	buf := fluent.NewBuffer(int(e.bufferhint.Load()))
	e.RenderBuilder(buf)
	e.bufferhint.Store(int64(buf.Len()))
	n, err := buf.WriteTo(w)
	fluent.PutBuffer(buf)
	return n, err
}

// RenderBytes returns the element's HTML as a byte slice, recording the
// measured size for later renders like WriteTo does.
func (e *clipPath) RenderBytes() []byte {
	buf := bytes.NewBuffer(make([]byte, 0, int(e.bufferhint.Load())))
	e.RenderBuilder(buf)
	e.bufferhint.Store(int64(buf.Len()))
	return buf.Bytes()
}

// AttributeBuilder writes all attributes for the element to the buffer.
func (e *clipPath) AttributeBuilder(buf *bytes.Buffer) {
	if len(e.clipPathUnits) > 0 {
		buf.Write(AttrClipPathUnits)
		buf.Write(e.clipPathUnits)
		buf.Write(MarkupQuote)
	}

	if e.dynamic != "" {
		key := node.EscapeAttribute(e.dynamic)
		var id string
		if e.sa != nil {
			id = e.sa.ID
		}
		if id == "" {
			buf.Write(AttrID)
			buf.WriteString(key)
			buf.Write(MarkupQuote)
		} else if id != key {
			panic("fluent: ID " + id + " conflicts with Dynamic key " + e.dynamic + " - a Dynamic key renders as the element's id, so set one or the other")
		}
	}

	if e.attr != nil {
		for _, attr := range *e.attr {
			buf.Write(MarkupSpace)
			buf.WriteString(attr.Key)
			buf.Write(MarkupEquals)
			buf.Write(MarkupQuote)
			buf.WriteString(attr.Value)
			buf.Write(MarkupQuote)
		}
	}

	if e.sa != nil {
		e.sa.AttributeBuilder(buf)
	}

	if e.ea != nil {
		e.ea.AttributeBuilder(buf)
	}
}

// RenderBuilder writes the SVG representation directly to a buffer.
func (e *clipPath) RenderBuilder(buf *bytes.Buffer) {
	buf.Write(TagClipPath)
	e.AttributeBuilder(buf)
	buf.Write(MarkupCloseTag)
	for _, child := range e.nodes {
		if child != nil {
			child.RenderBuilder(buf)
		}
	}
	buf.Write(TagClipPathClose)
}

// RenderOpen writes the opening tag and attributes to the buffer.
func (e *clipPath) RenderOpen(buf *bytes.Buffer) {
	buf.Write(TagClipPath)
	e.AttributeBuilder(buf)
	buf.Write(MarkupCloseTag)
}

// RenderClose writes the closing tag to the buffer.
func (e *clipPath) RenderClose(buf *bytes.Buffer) {
	buf.Write(TagClipPathClose)
}

// Nodes returns a slice of child nodes.
func (e *clipPath) Nodes() []node.Node {
	return e.nodes
}

// Attributes returns a pointer to the underlying attributes slice for direct attribute manipulation.
func (e *clipPath) Attributes() *[]node.Attribute {
	if e.attr == nil {
		slice := make([]node.Attribute, 0, 1)
		e.attr = &slice
	}
	return e.attr
}

// isSVGShape seals clipPath as a Shape.
func (*clipPath) isSVGShape() {}

// isSVGShapeContent seals clipPath as a ShapeContent.
func (*clipPath) isSVGShapeContent() {}
